const controls={preset:document.querySelector('#preset'),viewport:document.querySelector('#viewport'),cancellation:document.querySelector('#cancellation'),meal:document.querySelector('#meal'),price:document.querySelector('#price'),special:document.querySelector('#special'),rack:document.querySelector('#rack'),vat:document.querySelector('#vat'),commission:document.querySelector('#commission')};
const preview=document.querySelector('#snippetPreview');const previewContext=document.querySelector('#previewContext');const workbench=document.querySelector('.snippet-workbench');
controls.preset.innerHTML=HotelOfferWidget.variants.map(item=>`<option value="${item.id}">${item.title}</option>`).join('')+'<option value="custom" disabled>Пользовательский</option>';
const viewportModes={'desktop-1440':{label:'Экран 1440 px · снипет 986 px',width:986},'desktop-1280':{label:'Экран 1280 px · снипет 986 px',width:986},'hotel-grid':{label:'2 колонки · снипет 792 px',width:792}};
const readSettings=()=>({id:'custom',cancellation:controls.cancellation.value,meal:controls.meal.value,price:controls.price.value||'33 000 ₽',special:controls.special.checked,rack:controls.rack.checked,vat:controls.vat.checked,commission:controls.commission.checked});
const render=()=>{const viewport=viewportModes[controls.viewport.value];preview.style.setProperty('--snippet-width',`${viewport.width}px`);workbench.style.setProperty('--preview-column-width',`${viewport.width+28}px`);workbench.style.setProperty('--workbench-width',`${viewport.width+388}px`);previewContext.textContent=viewport.label;HotelOfferWidget.render(preview,readSettings())};
const applyPreset=id=>{const item=HotelOfferWidget.get(id);Object.entries(item).forEach(([key,value])=>{if(!(key in controls))return;if(controls[key].type==='checkbox')controls[key].checked=value;else controls[key].value=value});render()};
controls.preset.addEventListener('change',()=>applyPreset(controls.preset.value));Object.entries(controls).filter(([key])=>key!=='preset').forEach(([key,control])=>control.addEventListener(control.type==='text'?'input':'change',()=>{if(key!=='viewport')controls.preset.value='custom';render()}));controls.viewport.value='desktop-1440';applyPreset('full-penalty');
